solution.code:
import statistics

def summary(data):
    return {'mean': statistics.mean(data), 'median': statistics.median(data),
            'stdev': round(statistics.stdev(data), 2)}

import statistics

def outliers(data):
    m = statistics.mean(data)
    sd = statistics.pstdev(data)
    return sorted(x for x in data if abs(x - m) > 2 * sd)

