import numpy as np

def apply_vat(prices):
    return np.round(np.array(prices) * 1.2, 2)

import numpy as np

def curve(scores, target):
    shift = target - scores.mean()
    return np.round(np.clip(scores + shift, 0, 100), 1)

import numpy as np

def bmi(weights_kg, heights_cm):
    return np.round(weights_kg / (heights_cm / 100) ** 2, 1)

