import numpy as np

def fill_missing(arr):
    fill = round(float(np.nanmean(arr)), 2)
    return np.where(np.isnan(arr), fill, arr)

import numpy as np

def dice_stats(n, seed):
    rolls = np.random.default_rng(seed).integers(1, 7, size=n)
    counts = [int((rolls == f).sum()) for f in range(1, 7)]
    return {'min': int(rolls.min()), 'max': int(rolls.max()), 'counts': counts}
